    if (m.method === 'Log.entryAdded' && ['error', 'warning'].includes(m.params.entry.level)) {
      logs.push('LOG.' + m.params.entry.level.toUpperCase() + ': ' + m.params.entry.text + ' ' + (m.params.entry.url || ''));
