  ws.addEventListener('message', onMsg);

  await send('Runtime.enable', {}, sessionId);
  await send('Log.enable', {}, sessionId);
  await send('Page.enable', {}, sessionId);
  await send('Emulation.setDeviceMetricsOverride',
    { width: w, height: 900, deviceScaleFactor: 1, mobile: w < 768 }, sessionId);

  await send('Page.navigate', { url: FILE }, sessionId);
  await sleep(1000);

  const probe = [
    '(() => {',
    '  const d = document.documentElement, vw = d.clientWidth;',
    '  const out = { viewport: vw, scrollWidth: d.scrollWidth, overflowPx: d.scrollWidth - vw };',
    '  const off = [];',
    '  for (const el of document.querySelectorAll("body *")) {',
    '    const r = el.getBoundingClientRect();',
    '    if (!r.width && !r.height) continue;',
    '    if (r.right > vw + 1 || r.left < -1) {',
    '      const cn = typeof el.className === "string" ? el.className : (el.className.baseVal || "");',
    '      off.push(el.tagName.toLowerCase() + (cn ? "." + cn.trim().split(/\\s+/).join(".") : "") + "[" + Math.round(r.left) + "->" + Math.round(r.right) + "]");',
    '    }',
    '  }',
    '  out.offenders = off.slice(0, 15);',
