    const dark = [
      '(() => {',
      '  const d = document.documentElement;',
      '  const lum = c => { const p = c.match(/[\\d.]+/g).map(Number).slice(0,3).map(v => { v/=255; return v<=0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055,2.4); }); return 0.2126*p[0]+0.7152*p[1]+0.0722*p[2]; };',
      '  const ratio = (a,b) => { const x = lum(a), y = lum(b), hi = Math.max(x,y), lo = Math.min(x,y); return +((hi+0.05)/(lo+0.05)).toFixed(2); };',
      '  const bg = getComputedStyle(document.body).backgroundColor;',
      '  const q = s => getComputedStyle(document.querySelector(s));',
      '  const pairs = [',
      '    ["正文 body text", q("body").color, bg],',
      '    ["hero 副文案 hero-lead", q(".hero-lead").color, bg],',
      '    ["hero 小字 hero-note", q(".hero-note").color, bg],',
      '    ["卡片正文 card p", q(".card p").color, q(".card").backgroundColor],',
      '    ["区块副文案 section-head p", q(".section-head p").color, q(".section--alt").backgroundColor],',
      '    ["页脚链接 footer a", q(".footer-col a").color, q(".site-footer").backgroundColor],',
      '    ["页脚版权 footer-bottom", q(".footer-bottom").color, q(".site-footer").backgroundColor],',
      '    ["eyebrow 标签", q(".eyebrow").color, q(".eyebrow").backgroundColor],',
      '    ["价格 plan amount", q(".plan-price .amount").color, q(".plan").backgroundColor],',
      '    ["kicker 小标", q(".kicker").color, bg],',
      '    ["主按钮 btn--primary", q(".btn--primary").color, q(".btn--primary").backgroundColor],',
      '    ["推荐徽标 plan-badge", q(".plan-badge").color, q(".plan-badge").backgroundColor],',
      '    ["方案说明 plan-desc", q(".plan-desc").color, q(".plan").backgroundColor],',
      '    ["field hint", q(".field-hint").color, q(".form-card").backgroundColor],',
      '    ["input 文字", q("#email").color, q("#email").backgroundColor],',
      '  ];',
      '  const res = {};',
      '  for (const [k, fg, b] of pairs) res[k] = ratio(fg, b);',
      '  return { theme: d.getAttribute("data-theme"), colorScheme: getComputedStyle(d).colorScheme, ratios: res };',
      '})()',
    ].join('\n');
    report.dark = (await send('Runtime.evaluate', { expression: dark, returnByValue: true }, sessionId)).result.result.value;

    const formTest = [
      '(async () => {',
      '  const inp = document.querySelector("#email"), err = document.querySelector("#email-error");',
      '  const form = document.querySelector("#signupForm");',
      '  const out = [];',
      '  const step = v => {',
      '    inp.value = v;',
      '    form.dispatchEvent(new Event("submit", { cancelable: true, bubbles: true }));',
      '    return { value: v, errorShown: err.classList.contains("is-shown"), msg: document.querySelector("#email-error-text").textContent, ariaInvalid: inp.getAttribute("aria-invalid"), focusBackOnField: document.activeElement === inp };',
      '  };',
      '  for (const v of ["", "abc", "a@@b.com", "abc@localhost", "name@example.com"]) out.push(step(v));',
      '  const st = document.querySelector("#formStatus");',
      '  return { steps: out, successShown: st.classList.contains("is-shown"), status: st.textContent.trim() };',
      '})()',
    ].join('\n');
    report.form = (await send('Runtime.evaluate', { expression: formTest, returnByValue: true, awaitPromise: true }, sessionId)).result.result.value;

    const kbTest = [
      '(() => {',
      '  const els = [...document.querySelectorAll("a[href],button:not([disabled]),input,[tabindex]:not([tabindex=\\"-1\\"])")];',
      '  const noRing = [];',
      '  for (const el of els) {',
      '    el.focus();',
      '    const s = getComputedStyle(el);',
      '    if (document.activeElement !== el) continue;',
      '    const ow = parseFloat(s.outlineWidth) || 0;',
      '    if (ow < 1 || s.outlineStyle === "none") noRing.push((el.textContent || el.id || el.tagName).trim().slice(0, 22));',
      '  }',
      '  return { focusableCount: els.length, focusableWithoutRing: noRing, toggleAriaLabel: document.querySelector("#themeToggle").getAttribute("aria-label"), toggleVisibleText: document.querySelector("#themeLabel").textContent };',
      '})()',
    ].join('\n');
    report.keyboard = (await send('Runtime.evaluate', { expression: kbTest, returnByValue: true }, sessionId)).result.result.value;

    await send('Runtime.evaluate', { expression: 'document.documentElement.setAttribute("data-theme","light"); try{localStorage.setItem("nightride-theme","light")}catch(e){}' }, sessionId);
