    const light = dark.replace('data-theme")', 'data-theme")');
    report.light = (await send('Runtime.evaluate', { expression: light, returnByValue: true }, sessionId)).result.result.value;
  }

  if (w === 390 || w === 1280) {
    const shot = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true }, sessionId);
