import { spawn } from 'node:child_process';

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const FILE = 'file:///C:/Users/yu.zhao/AppData/Local/Temp/skill-up-649008052/index.html';
const PORT = 9334;

const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-sandbox', '--hide-scrollbars',
  '--no-first-run', '--no-default-browser-check',
  '--remote-debugging-port=' + PORT,
  '--user-data-dir=' + process.cwd() + '/_cdpprofile2',
  'about:blank',
], { stdio: 'ignore' });

const sleep = ms => new Promise(r => setTimeout(r, ms));
async function wsUrl() {
  for (let i = 0; i < 60; i++) {
    try { return (await (await fetch('http://127.0.0.1:' + PORT + '/json/version')).json()).webSocketDebuggerUrl; }
    catch { await sleep(250); }
  }
  throw new Error('no chrome');
}
const ws = new WebSocket(await wsUrl());
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map();
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
const send = (method, params = {}, sessionId) => {
  const msgId = ++id;
  return new Promise(res => { pending.set(msgId, res); ws.send(JSON.stringify({ id: msgId, method, params, ...(sessionId ? { sessionId } : {}) })); });
};

const t = await send('Target.createTarget', { url: 'about:blank' });
const targetId = t.result.targetId;
const sessionId = (await send('Target.attachToTarget', { targetId, flatten: true })).result.sessionId;
await send('Runtime.enable', {}, sessionId);
await send('Page.enable', {}, sessionId);
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true }, sessionId);
await send('Page.navigate', { url: FILE }, sessionId);
await sleep(1000);

const out = {};

// 1. sticky header still sticks?
out.sticky = (await send('Runtime.evaluate', { expression: `(() => {
  const h = document.querySelector('.site-header');
  const before = Math.round(h.getBoundingClientRect().top);
  window.scrollTo(0, 2000);
  const mid = Math.round(h.getBoundingClientRect().top);
  const scrollY = Math.round(window.scrollY);
  window.scrollTo(0, document.body.scrollHeight);
  const bottom = Math.round(h.getBoundingClientRect().top);
  window.scrollTo(0, 0);
  return { topBeforeScroll: before, topAfterScroll2000: mid, scrollY, topAtPageBottom: bottom };
})()`, returnByValue: true }, sessionId)).result.result.value;

// 2. tab order walk
out.tabOrder = (await send('Runtime.evaluate', { expression: `(() => {
  const sel = 'a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])';
  const els = [...document.querySelectorAll(sel)];
  return els.map((el, i) => {
    const r = el.getBoundingClientRect();
    const label = (el.getAttribute('aria-label') || el.textContent || el.id || el.tagName).trim().replace(/\\s+/g, ' ').slice(0, 30);
    return (i + 1) + '. <' + el.tagName.toLowerCase() + '> ' + label + '  y=' + Math.round(r.top + window.scrollY);
  });
})()`, returnByValue: true }, sessionId)).result.result.value;

// 3. anchor targets all resolve, and scroll-padding keeps heading clear of the sticky header
out.anchors = (await send('Runtime.evaluate', { expression: `(async () => {
  const res = [];
  for (const a of document.querySelectorAll('a[href^="#"]')) {
    const hash = a.getAttribute('href');
    const target = hash === '#top' ? document.body : document.querySelector(hash);
    if (!target) { res.push(hash + ' -> MISSING'); continue; }
    a.click();
    await new Promise(r => setTimeout(r, 700));
    const top = Math.round(target.getBoundingClientRect().top);
    const headerBottom = Math.round(document.querySelector('.site-header').getBoundingClientRect().bottom);
    res.push(hash + ' ok, 落点 top=' + top + ', header 底部=' + headerBottom + (top >= headerBottom - 1 ? ' 未被遮挡' : ' 被遮挡!'));
  }
  window.scrollTo(0, 0);
  return res;
})()`, returnByValue: true, awaitPromise: true }, sessionId)).result.result.value;

// 4. tap-target spacing on mobile (neighbouring controls not overlapping)
out.overlaps = (await send('Runtime.evaluate', { expression: `(() => {
  const els = [...document.querySelectorAll('a[href],button,input')].map(e => ({ e, r: e.getBoundingClientRect() })).filter(x => x.r.width > 0);
  const bad = [];
  for (let i = 0; i < els.length; i++) for (let j = i + 1; j < els.length; j++) {
    const a = els[i].r, b = els[j].r;
    if (a.left < b.right - 2 && b.left < a.right - 2 && a.top < b.bottom - 2 && b.top < a.bottom - 2) {
      bad.push(els[i].e.textContent.trim().slice(0,12) + ' ⟂ ' + els[j].e.textContent.trim().slice(0,12));
    }
  }
  return bad;
})()`, returnByValue: true }, sessionId)).result.result.value;

// 5. theme toggle full cycle + persistence
out.themeCycle = (await send('Runtime.evaluate', { expression: `(() => {
  const btn = document.querySelector('#themeToggle'), d = document.documentElement;
  const seq = [];
  const snap = () => d.getAttribute('data-theme') + ' / 显示"' + document.querySelector('#themeLabel').textContent + '" / ' + getComputedStyle(d).colorScheme;
  seq.push('初始(系统浅色) ' + snap());
  for (let i = 0; i < 3; i++) { btn.click(); seq.push('点击' + (i+1) + ' ' + snap()); }
  let stored = 'n/a'; try { stored = localStorage.getItem('nightride-theme'); } catch(e) { stored = 'unavailable'; }
  return { seq, stored };
})()`, returnByValue: true }, sessionId)).result.result.value;

// 6. prefers-reduced-motion respected
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] }, sessionId);
out.reducedMotion = (await send('Runtime.evaluate', { expression: `(() => {
  const r = document.querySelector('.art-route');
  const s = getComputedStyle(r);
  return { animationDuration: s.animationDuration, animationName: s.animationName, htmlScrollBehavior: getComputedStyle(document.documentElement).scrollBehavior };
})()`, returnByValue: true }, sessionId)).result.result.value;

console.log(JSON.stringify(out, null, 1));
ws.close(); chrome.kill(); process.exit(0);

